function pos(z){
  if(z===1) return [1,1]; if(z===2) return [1,18];
  if(z<=4) return [2,z-2]; if(z<=10) return [2,z+8];
  if(z<=12) return [3,z-10]; if(z<=18) return [3,z];
  if(z<=36) return [4,z-18]; if(z<=54) return [5,z-36];
  if(z<=56) return [6,z-54]; if(z===57) return [6,3];
  if(z<=71) return [9,z-54]; if(z<=86) return [6,z-68];
  if(z<=88) return [7,z-86]; if(z===89) return [7,3];
  if(z<=103) return [10,z-86]; return [7,z-100];
}
A.EL = [null];
RAW.split(";").forEach(s=>{
  const [z,sym,name,m]=s.split(",");
  const Z=+z, [row,col]=pos(Z);
  const est = m.startsWith("(");
  const mass = parseFloat(m.replace(/[()]/g,""));
  const fblock = row>=9;
  const period = fblock ? (row===9?6:7) : row;
  A.EL.push({Z, sym, name, massStr:m.replace(/[()]/g,""), mass, est, row, col, group: fblock?null:col, period, A: Math.round(mass)});
});
A.bySym = {}; A.EL.forEach(e=>{ if(e) A.bySym[e.sym.toLowerCase()] = e; });
A.isMain = Z => { const g=A.EL[Z].group; return g===1||g===2||(g>=13&&g<=18); };
A.valence = Z => { const g=A.EL[Z].group; if(Z===2) return 2; if(g===1||g===2) return g; if(g>=13&&g<=18) return g-10; return null; };

