  const OK={m:["k","c","m","μ","n"],g:["k","m","μ"],L:["m","μ"],J:["k"],s:["m","μ","n"]};
  const g=A.Game(host,{how:"Decide which unit is larger, plug the numbers into the dotted boxes, then calculate. You can type the factor as 1000, or as 10, a space, then the exponent (10 3 becomes 10³)."});
  g.button("New problem",()=>next(),"ghost");
  g.stage.innerHTML=`<div class="qp"><small>Convert</small><div class="qp-t num" id="mc-q"></div></div><h4 class="stp"><b>1</b>Multiply or divide?</h4><div class="qc"><div class="qc-o col" id="mc-o"></div></div><h4 class="stp locked" id="mc-h2"><b>2</b>Plug in the numbers and calculate</h4><div id="mc-c"></div>`;
  const nice=v=>{ const a=Math.abs(v); if(a!==0&&(a>=1e7||a<1e-4)) return L.sci(v,Math.min(6,String(+v.toPrecision(6)).replace(/[^\d]/g,"").replace(/^0+/,"").length||1)).html; return L.commas(String(+v.toPrecision(8))); };
