      const win=()=>{ g.win(); g.msg(`✔ ${v} ${from} = ${nice(ans)} ${to}. ${toSmaller?`A ${to} is smaller than a ${from}, so there are more of them.`:`A ${to} is larger than a ${from}, so there are fewer of them.`}`,"good"); g.later(next,3200); };
