    if(F().melt==="burn"&&rec[k]&&rec[k].heat&&rec[k].heat.startsWith("burns")&&!st.aq) s+=`<circle cx="${SX}" cy="${SY-10}" r="${30+Math.sin(now/50)*4}" fill="#fff" opacity=".9"/><circle cx="${SX}" cy="${SY-10}" r="50" fill="#fffbe0" opacity=".5"/>`;
    /* hammer swing */
