    s+=tl("hammer",`<rect x="-6" y="-30" width="12" height="56" rx="3" fill="#a0703c" stroke="#5a3d1e"/><rect x="-24" y="-38" width="48" height="18" rx="3" fill="#6b7a82" stroke="#2c3438"/>`,"hammer");
