    s+=tl("water",`<path d="M-20 -26V18H20V-26" fill="#e4f3fb" stroke="#5f6b72" stroke-width="2"/><rect x="-18" y="-8" width="36" height="24" fill="#bfe3f5"/>`,"beaker of water");
    const [lx,ly]=tools.lens; const inner= lensOn? B.substPic(k).replace("<svg ",`<svg x="-62" y="-46" width="124" height="92" `) : "";
