  el.innerHTML=`<div class="r5-row">${all.map((f,i)=>`${i===n?`<span class="r5-ar big">→</span>`:i?`<span class="r5-op big">+</span>`:""}<span class="r5-cell" data-i="${i}"><button type="button" class="r5-up" data-d="1" aria-label="increase">▲</button><span class="r5-cv">1</span><button type="button" class="r5-dn" data-d="-1" aria-label="decrease">▼</button><span class="r5-f">${sub(f)}</span></span>`).join("")}</div><div class="r5-tab"></div>`;
