      if(st==="type") steps.push({title:"Synthesis or decomposition?",body:el=>choice(el,[["syn","Synthesis: two or more substances combine"],["dec","Decomposition: one compound breaks apart"]],"How many reactants are there?"),check:el=>!el._v?"Choose one.":el._v===(it.r.length===1?"dec":"syn")?true:(it.r.length===1?"There is only one reactant, and it breaks apart: decomposition.":"Two reactants combine into one product: synthesis."),good:it.r.length===1?"Decomposition: one reactant breaks apart.":"Synthesis: the reactants combine."});
