    $("eq").innerHTML=`<span class="da-given" data-r="given">${S.q(P0.gTxt,P0.given[1],P0.given[2])}</span>${fr}<span class="da-want">= <span class="blank">?</span> ${S.u(P0.want[0],P0.want[1])}</span>`;
